const input = $input.all().map(i => i.json);
const root = input.length === 1 ? input[0] : input;

const rawItems = Array.isArray(root)
  ? root
  : root.items ?? root.results ?? root.data ?? [];

function pick(...values) {
  for (const v of values) {
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return null;
}

function toDate(value) {
  if (!value) return null;
  if (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value)) return value;

  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return null;

  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function toList(value) {
  if (!value) return null;
  if (Array.isArray(value)) return value.filter(Boolean).join(', ') || null;
  if (typeof value === 'object') return Object.values(value).filter(Boolean).join(', ') || null;
  return String(value).trim() || null;
}

function recentlyReleased(releaseDate) {
  if (!releaseDate) return false;
  const now = new Date();
  const released = new Date(`${releaseDate}T00:00:00Z`);
  if (Number.isNaN(released.getTime())) return false;

  const diffDays = Math.floor((now.getTime() - released.getTime()) / 86400000);
  return diffDays >= 0 && diffDays <= 30;
}

const normalized = rawItems
  .map((item) => {
    const title = pick(item.title, item.name, item.romaji_title, item.english_title);
    const releaseDate = toDate(pick(item.release_date, item.releaseDate, item.date, item.start_date, item.aired_at));
    const cover = pick(item.cover, item.image, item.image_url, item.poster, item.poster_url, item.banner);
    const genre = toList(pick(item.genre, item.genres, item.category));
    const platform = toList(pick(item.platform, item.platforms, item.streaming, item.service, item.provider));
    const trailerUrl = pick(item.trailer_url, item.trailerUrl, item.trailer, item.video, item.youtube);

    return {
      title,
      cover,
      genre,
      platform,
      releaseDate,
      isRecentlyReleased: recentlyReleased(releaseDate),
      trailerUrl,
    };
  })
  .filter((it) => it.title && it.cover && it.platform && it.releaseDate);

const seen = new Set();
const items = [];
for (const it of normalized) {
  const key = `${it.title}__${it.releaseDate}`;
  if (seen.has(key)) continue;
  seen.add(key);
  items.push(it);
}

return [{ json: { total: items.length, items } }];

const items = $input.first().json.items ?? [];
const batchSize = 200;
const out = [];
for (let i = 0; i < items.length; i += batchSize) {
  out.push({ json: { items: items.slice(i, i + batchSize), batch: Math.floor(i / batchSize) + 1, total: items.length } });
}
return out.length ? out : [{ json: { items: [], batch: 1, total: 0 } }];

const responses = $input.all().map(i => i.json);
const total = $items("Normalize Anime")[0].json.total;

return [{
  json: {
    workflow: "anime",
    sent: total,
    batches: responses.length,
    apiResponses: responses,
    executedAt: new Date().toISOString(),
  }
}];
